Byte Pair Encoding was brought into neural machine translation by Sennrich, Haddow and Birch (ACL 2016) to handle rare words as sequences of smaller units. Training: split every word into characters, count every neighbouring pair, merge the most frequent pair, repeat. Tokenizing: replay the merges in the same order. Many modern tokenizers run the same idea on UTF-8 bytes, so any text can be encoded (see Dev Essentials 01 · Text Encoding).
# bpe_toy.py
from collections import Counter
def merge_pair(symbols, pair):
out, i = [], 0
while i < len(symbols):
if i < len(symbols) - 1 and (symbols[i], symbols[i + 1]) == pair:
out.append(symbols[i] + symbols[i + 1])
i += 2
else:
out.append(symbols[i])
i += 1
return tuple(out)
def train_bpe(corpus, num_merges):
words = Counter(tuple(w) + ("</w>",) for w in corpus.split()) # chars + end marker
merges = []
for _ in range(num_merges):
pairs = Counter()
for word, freq in words.items():
for a, b in zip(word, word[1:]):
pairs[(a, b)] += freq
if not pairs:
break
best = max(pairs, key=pairs.get) # most frequent pair
merges.append(best)
words = Counter({merge_pair(w, best): f for w, f in words.items()})
return merges
def tokenize(word, merges):
symbols = tuple(word) + ("</w>",)
for pair in merges:
symbols = merge_pair(symbols, pair)
return list(symbols)
